import{EXESNOHS_CONFIG as x}from"./config.min.js";const r=t=>t*t*(3-2*t),u=t=>1-(1-t)*(1-t);export function takedownLength(){const t=x.pose.takedown;return t.dive+t.fall+t.settle}export function takedownAt(t,e,s){const n=x.pose.takedown,o=s.x-e.x,a=s.z-e.z,d=Math.hypot(o,a)||1e-6,l=o/d,h=a/d,f=Math.max(0,d-n.close),c=Math.min(1,Math.max(0,t/n.dive)),i=Math.min(1,Math.max(0,(t-n.dive)/n.fall)),p=Math.sin(Math.PI*c)*n.leap,m=Math.max(0,1-i*1.6);return{tackler:{x:l*f*u(c),y:p*m,z:h*f*u(c),lean:n.tacklerLean*r(c)},carrier:{x:l*n.driven*r(i),z:h*n.driven*r(i),lean:n.carrierLean*r(i)},contact:c>=1?1:0}}export function tacklerFor(t,e){if(!e)return"";let s="",n=1/0;for(const o of t){if(o===e||o.settings.benched||o.settings.position==="ball"||o.settings.team===e.settings.team)continue;const a=Math.hypot(o.coords.x-e.coords.x,o.coords.y-e.coords.y);a<n&&(n=a,s=o.settings.position)}return s}
